from pathlib import Path
p=Path('app/src/main/java/com/openai/rippledemo/MainActivity.java')
s=p.read_text(encoding='utf-8')
def rep(a,b,n):
    global s
    if a not in s: raise SystemExit('missing '+n)
    s=s.replace(a,b,1)
def btw(a,b,r,n):
    global s
    i=s.find(a);j=s.find(b,i)
    if i<0 or j<0: raise SystemExit('missing '+n)
    s=s[:i]+r+s[j:]
