# Dragging the edge orb past the commit distance now opens settings immediately.
btw('        private boolean handleSettingsOrbGesture','        private void openSettingsPanel',r'''        private boolean handleSettingsOrbGesture(MotionEvent e){float x=e.getX(),y=e.getY();RectF hit=settingsOrbHitRect(getWidth(),getHeight());int a=e.getActionMasked();if(a==MotionEvent.ACTION_DOWN){if(!hit.contains(x,y))return false;orbPointerId=e.getPointerId(0);orbDownX=x;orbDownY=y;orbDownAt=SystemClock.uptimeMillis();orbGestureIsDrag=false;orbState=ORB_ATTACHED_PRESSED;return true;}if(orbPointerId<0)return false;int idx=e.findPointerIndex(orbPointerId);if(idx<0)idx=0;x=e.getX(idx);y=e.getY(idx);if(a==MotionEvent.ACTION_MOVE){float dx=x-orbDownX,dy=y-orbDownY;if(Math.hypot(dx,dy)>dp(6))orbGestureIsDrag=true;if(orbGestureIsDrag){orbPull=clampF(orbDownX-x,0,maxOrbPull());orbState=orbPull>detachThreshold()?ORB_DETACHED_DRAGGING:ORB_STRETCHING;if(orbPull>=openThreshold()){float origin=orbPull;orbPointerId=-1;openSettingsPanel(origin);return true;}invalidate();}return true;}if(a==MotionEvent.ACTION_UP||a==MotionEvent.ACTION_CANCEL){long dur=SystemClock.uptimeMillis()-orbDownAt;boolean tap=a==MotionEvent.ACTION_UP&&!orbGestureIsDrag&&dur<=350;orbPointerId=-1;if(tap){orbPull=0;openSettingsPanel(0);}else startOrbReturn();return true;}return true;}

''','orb gesture')

btw('        private void openSettingsPanel','        private void handleSettingRow',r'''        private void openSettingsPanel(float origin){settingsOpen=true;panelClosing=false;setupOpen=false;setupClosing=false;pickerType=PICK_NONE;pickerClosing=false;panelOpenedAt=SystemClock.uptimeMillis();panelOriginPull=origin;orbPull=0;orbState=ORB_PANEL_OPEN;invalidate();}
        private void closeSettingsPanel(){if(!settingsOpen||panelClosing)return;pickerType=PICK_NONE;pickerClosing=false;setupOpen=false;setupClosing=false;panelClosing=true;panelOpenedAt=SystemClock.uptimeMillis();postInvalidateOnAnimation();}
        private void startOrbReturn(){orbReturnFrom=orbPull;orbReturnStartedAt=SystemClock.uptimeMillis();orbState=ORB_RETURNING;postInvalidateOnAnimation();}
        private void updateOrbReturn(long now){if(orbState!=ORB_RETURNING)return;float q=clamp01((now-orbReturnStartedAt)/(float)ORB_RETURN_MS);orbPull=orbReturnFrom*(1f-returnEase(q));if(q>=1f){orbPull=0;orbState=ORB_ATTACHED_IDLE;}}
        private float panelProgress(long now){float q=clamp01((now-panelOpenedAt)/(float)PANEL_ANIM_MS);return panelClosing?1f-easeOutCubic(q):easeOutCubic(q);}
        private void updatePanelAnimations(long now){if(panelClosing&&now-panelOpenedAt>=PANEL_ANIM_MS){panelClosing=false;settingsOpen=false;orbState=ORB_ATTACHED_IDLE;panelOriginPull=0;}if(setupClosing&&now-setupAnimAt>=250){setupClosing=false;setupOpen=false;}if(pickerClosing&&now-pickerAnimAt>=180){pickerClosing=false;pickerType=PICK_NONE;}}
        private void openSetupPage(){setupOpen=true;setupClosing=false;setupAnimAt=SystemClock.uptimeMillis();postInvalidateOnAnimation();}
        private void closeSetupPage(){if(!setupOpen||setupClosing)return;setupClosing=true;setupAnimAt=SystemClock.uptimeMillis();postInvalidateOnAnimation();}
        private float setupProgress(long now){if(!setupOpen&&!setupClosing)return 0f;float q=clamp01((now-setupAnimAt)/250f);return setupClosing?1f-easeOutCubic(q):easeOutCubic(q);}
        private void openPicker(int type){pickerType=type;pickerClosing=false;pickerAnimAt=SystemClock.uptimeMillis();postInvalidateOnAnimation();}
        private void beginClosePicker(){if(pickerType==PICK_NONE||pickerClosing)return;pickerClosing=true;pickerAnimAt=SystemClock.uptimeMillis();postInvalidateOnAnimation();}
        private float pickerProgress(long now){if(pickerType==PICK_NONE)return 0f;float q=clamp01((now-pickerAnimAt)/180f);return pickerClosing?1f-easeOutCubic(q):easeOutCubic(q);}

''','panel state')

btw('        private void handleSettingRow','        private void openSystemSettings',r'''        private void handleSettingRow(int i){if(i==0)openPicker(PICK_SURFACE);else if(i==1)openPicker(PICK_LANGUAGE);else if(i==2)openPicker(PICK_FEEDBACK);else if(i==3)openPicker(PICK_DEBUG);else if(i==4)openSetupPage();else if(i==5){clearCode();closeSettingsPanel();}invalidate();}
        private void handleSetupRow(int i){if(i==0){lockscreenMode=!lockscreenMode;prefs.edit().putBoolean(KEY_LOCK_MODE,lockscreenMode).apply();applyLockscreenMode(lockscreenMode);}else if(i==1)requestHomeRole();else if(i==2)openPicker(PICK_HOME_APP);else if(i==3)openSystemSettings(Settings.ACTION_MANAGE_OVERLAY_PERMISSION);else if(i==4)openSystemSettings(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS);else if(i==5)openSystemSettings(Settings.ACTION_SECURITY_SETTINGS);else if(i==6)closeSetupPage();invalidate();}

''','handlers')

btw('        private String[] pickerItems()','        private void finalizeSequence()',r'''        private String[] pickerItems(){if(pickerType==PICK_SURFACE){String[] r=new String[styles.size()];for(int i=0;i<styles.size();i++)r[i]=styles.get(i).name;return r;}if(pickerType==PICK_LANGUAGE)return new String[]{"한국어","English"};if(pickerType==PICK_FEEDBACK)return language==LANG_KR?new String[]{"진동","시계 틴트"}:new String[]{"Vibration","Clock tint"};if(pickerType==PICK_DEBUG)return new String[]{"OFF","ON"};if(pickerType==PICK_HOME_APP){List<ResolveInfo> c=homeCandidates();String[] r=new String[c.size()];for(int i=0;i<c.size();i++){CharSequence l=c.get(i).loadLabel(getPackageManager());r[i]=l==null?c.get(i).activityInfo.packageName:l.toString();}return r;}return null;}
        private int pickerSelection(){if(pickerType==PICK_SURFACE)return selectedStyle;if(pickerType==PICK_LANGUAGE)return language;if(pickerType==PICK_FEEDBACK)return failFeedback;if(pickerType==PICK_DEBUG)return debugMode?1:0;if(pickerType==PICK_HOME_APP){List<ResolveInfo> c=homeCandidates();for(int i=0;i<c.size();i++){ComponentName cn=new ComponentName(c.get(i).activityInfo.packageName,c.get(i).activityInfo.name);if(cn.flattenToString().equals(homeTarget))return i;}return -1;}return 0;}
        private void applyPickerSelection(int i){if(pickerType==PICK_SURFACE){selectedStyle=clamp(i,0,styles.size()-1);prefs.edit().putInt(KEY_STYLE,selectedStyle).apply();}else if(pickerType==PICK_LANGUAGE){language=clamp(i,0,1);prefs.edit().putInt(KEY_LANG,language).apply();}else if(pickerType==PICK_FEEDBACK){failFeedback=clamp(i,0,1);prefs.edit().putInt(KEY_FEEDBACK,failFeedback).apply();}else if(pickerType==PICK_DEBUG){debugMode=i==1;prefs.edit().putBoolean(KEY_DEBUG,debugMode).apply();}else if(pickerType==PICK_HOME_APP){List<ResolveInfo> c=homeCandidates();if(i>=0&&i<c.size()){ResolveInfo ri=c.get(i);homeTarget=new ComponentName(ri.activityInfo.packageName,ri.activityInfo.name).flattenToString();prefs.edit().putString(KEY_HOME_TARGET,homeTarget).apply();}}}

''','picker methods')

rep('        private float maxOrbPull(){return Math.min(dp(230),getWidth()*.42f);}\n        private float detachThreshold(){return Math.min(dp(124),maxOrbPull()*.74f);}\n','        private float maxOrbPull(){return Math.min(dp(230),getWidth()*.42f);}\n        private float detachThreshold(){return Math.min(dp(124),maxOrbPull()*.74f);}\n        private float openThreshold(){return Math.min(dp(102),maxOrbPull()*.60f);}\n','open threshold')
rep('        private RectF setupRowRect(int i,float w,float h){RectF s=settingsSheetRect(w,h);float top=s.top+dp(78)+i*dp(58);return new RectF(s.left+dp(16),top,s.right-dp(16),top+dp(49));}\n        private RectF pickerRect(float w,float h,int count){float boxW=Math.min(w-dp(68),dp(300)),itemH=dp(49),boxH=dp(24)+count*itemH;return new RectF(w/2-boxW/2,h/2-boxH/2,w/2+boxW/2,h/2+boxH/2);}\n','        private RectF setupRowRect(int i,float w,float h){RectF s=settingsSheetRect(w,h);float top=s.top+dp(74)+i*dp(55);return new RectF(s.left+dp(16),top,s.right-dp(16),top+dp(46));}\n        private RectF pickerAnchorRect(float w,float h){if(pickerType==PICK_HOME_APP)return setupRowRect(2,w,h);int row=pickerType==PICK_SURFACE?0:pickerType==PICK_LANGUAGE?1:pickerType==PICK_FEEDBACK?2:3;return settingsRowRect(row,w,h);}\n        private RectF pickerRect(float w,float h,int count){RectF sh=settingsSheetRect(w,h),a=pickerAnchorRect(w,h);float bw=Math.min(sh.width()-dp(28),dp(286)),ih=dp(49),bh=dp(20)+count*ih,right=a.right,left=right-bw,top=a.bottom+dp(8);if(top+bh>sh.bottom-dp(12))top=a.top-dp(8)-bh;return new RectF(left,top,right,top+bh);}\n','geometry')
